def migrar_perfis(apps, schema_editor):
    Perfil = apps.get_model("utilizadores", "Perfil")
    Aluno = apps.get_model("utilizadores", "Aluno")
    Staff = apps.get_model("utilizadores", "Staff")
    PreferenciasUtilizador = apps.get_model(
        "utilizadores",
        "PreferenciasUtilizador"
    )

    emails_processados = set()

    perfis = Perfil.objects.select_related(
        "utilizador",
        "curso"
    ).all()

    for perfil in perfis:
        utilizador = perfil.utilizador
        email = (utilizador.email or "").strip()

        if not email:
            raise ValueError(
                f"O utilizador {utilizador.id} não tem email."
            )

        email_normalizado = email.casefold()

        if email_normalizado in emails_processados:
            raise ValueError(f"Email duplicado encontrado: {email}")

        emails_processados.add(email_normalizado)

        if perfil.tipo == "aluno":
            if not perfil.curso_id:
                raise ValueError(
                    f"O aluno {perfil.nome_completo} não tem curso."
                )

            Aluno.objects.create(
                utilizador_id=utilizador.id,
                nome=perfil.nome_completo,
                email=email,
                curso_id=perfil.curso_id,
            )

        elif perfil.tipo == "staff":
            Staff.objects.create(
                utilizador_id=utilizador.id,
                nome=perfil.nome_completo,
                email=email,
            )

        else:
            raise ValueError(
                f"Tipo de perfil desconhecido: {perfil.tipo}"
            )

        PreferenciasUtilizador.objects.create(
            utilizador_id=utilizador.id,
            idioma=perfil.idioma,
        )


